def certify_strategy_sixty_source(*, source_overrides=None):
    overrides = source_overrides or {}
    if set(STRATEGY60_SOURCE_AST) != set(REQUIRED_SOURCE_FILES):
        raise ValueError('Strategy60 complete source review is not sealed')
    if set(overrides) - set(STRATEGY60_SOURCE_AST):
        raise ValueError('Strategy60 source override is outside reviewed authority')
    root = Path(__file__).parents[2]
    observed = []
    for relative, expected in STRATEGY60_SOURCE_AST.items():
        source = Path(overrides.get(relative, root / relative)).read_text(encoding='utf-8')
        try:
            tree = ast.parse(source)
        except SyntaxError as exc:
            raise ValueError('Strategy60 source cannot be parsed: ' + relative) from exc
        if sha256(ast.unparse(tree).encode()).hexdigest() != expected:
            raise ValueError('Strategy60 pinned source changed: ' + relative)
        observed.append((relative, sha256(source.encode()).hexdigest()))
    return sha256(json.dumps(observed, separators=(',', ':')).encode()).hexdigest()
